package com.shazwan.idash.a1lab.target;
import android.app.*;import android.os.*;import android.content.*;import java.util.concurrent.*;
/** Primary-screen self-test only, explicitly not an embedding test. */
public final class TargetChecks extends Instrumentation {
 int count;ProbeActivity a;volatile IBinder binder;boolean bound;ServiceConnection connection;void check(boolean ok,String text){if(!ok)throw new AssertionError(text);count++;}void ui(Runnable task){Throwable[] e={null};runOnMainSync(()->{try{task.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  a=(ProbeActivity)startActivitySync(new Intent(getTargetContext(),ProbeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(ProbeActivity.display==0,"standalone is primary display; no embedding claim");ui(()->{int before=ProbeActivity.count.get();((android.widget.Button)a.content.getChildAt(1)).performClick();check(ProbeActivity.count.get()==before+1,"own counter UI click");a.section="Search";a.render();a.search.setText("probe text");check("probe text".equals(ProbeActivity.lastInput),"own text input stored");a.onBackPressed();check("Library".equals(a.section),"Back returns Library");((android.widget.Button)a.content.getChildAt(3)).performClick();check(a.popup!=null&&a.popup.isShowing(),"own app dialog shown");a.onBackPressed();check(!a.popup.isShowing(),"Back dismisses own dialog");a.playTone();check(ProbeActivity.playing&&a.focusRequest!=null,"AudioFocus granted for synthetic test tone");a.stopAudio();check(!ProbeActivity.playing&&a.focusRequest==null&&a.tone==null,"tone/focus resources released");});
  connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){binder=b;}public void onServiceDisconnected(ComponentName n){binder=null;}};ui(()->bound=a.bindService(new Intent(a,Bridge.class),connection,Context.BIND_AUTO_CREATE));long end=SystemClock.elapsedRealtime()+15000;while(binder==null&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(binder!=null,"self-UID test client bound");Parcel data=Parcel.obtain(),reply=Parcel.obtain();boolean denied=false;try{data.writeInterfaceToken(Bridge.TOKEN);binder.transact(8,data,reply,0);reply.readException();}catch(SecurityException expected){denied=true;}finally{data.recycle();reply.recycle();}check(denied,"target UID cannot impersonate explicitly pinned host UID even though signer matches");
  ui(()->{a.playTone();a.finish();});end=SystemClock.elapsedRealtime()+5000;while(!a.isDestroyed()&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(a.isDestroyed()&&!ProbeActivity.playing&&a.focusRequest==null,"Activity destruction releases audio focus");result.putString("stream","PASS: "+count+" standalone-target/security/audio checks\nNOT secondary-display touch, keyboard, native resize or BitChord playback. Tone is synthetic; physical sound unverified.\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n");}finally{if(a!=null)ui(()->{if(bound){a.unbindService(connection);bound=false;}a.stopAudio();a.finish();});}finish(code,result);}
}
